#!/usr/bin/env python3
"""Generate the addon's bundled soundtrack sets from soundtrack pack JSON.

A *soundtrack set* is a named list of needle drops (place -> song). Bundled sets are authored as
pack JSON files (``packs/*.json``: docs/SPEC.md 3.7 plus the docs/SPEC-v1.2.md additions) and
shipped inside the addon as plain Lua 5.1 data files, one per pack, in
``addon/NeedleDropper/Sets/``::

    local ADDON, ns = ...
    -- Generated by tools/gen_sets.py from packs/azeroth-unbound.json. Edit the pack, not this file.
    ns.RegisterBuiltinSet({
      id = "azeroth-unbound", name = "Azeroth Unbound", author = "NeedleDropper", ..., version = 1, source = "packs/azeroth-unbound.json",
      drops = {
        { id = "area:150", kind = "subzone", mapID = 1437, areaID = 150, subzone = "Menethil Harbor", ... },
        { id = "zone:1429", kind = "zone", mapID = 1429, label = "Elwynn Forest", title = "...", ... },
      },
    })

docs/SETS-FORMAT.md is the full contract (accepted input, validation rules, emitted keys, the
``ns.RegisterBuiltinSet`` consumer contract). In short:

* zone names resolve to uiMapIDs and drop ids derive exactly as the companion does, through the
  companion's own ``needledropper.zones`` and ``needledropper.models.drop_id_for`` (read-only use);
* Spotify links/URIs become the bare 22-character track id, YouTube links the 11-character video id;
* drops are sorted by id (plain string sort), keys are written in a fixed order, text stays UTF-8
  and is Lua-escaped, and the file has no timestamp: the same pack always gives the same bytes;
* drops with ``"disabled": true`` are skipped; any invalid entry fails loudly, naming the pack file,
  the pack and the drop index (``pack "X" drops[3] (Goldshire): missing "artist"``).

Usage (from anywhere; default paths are anchored at the repository root)::

    python tools/gen_sets.py                       # every packs/*.json -> addon/NeedleDropper/Sets/
    python tools/gen_sets.py packs/a.json b.json --out addon/NeedleDropper/Sets
    python tools/gen_sets.py --check               # CI: write nothing, fail if anything is stale

Each pack is handled on its own: a broken pack is reported (and makes the exit status non-zero)
but does not stop the valid packs from being written. Output file name = CamelCase of the set id
(``azeroth-unbound`` -> ``AzerothUnbound.lua``). Files are only rewritten when their content
changes, atomically, and never when the existing file was not produced by this tool.

Exit status: 0 = everything valid and written (or up to date under ``--check``); 1 = an invalid
pack, a refused write, or (``--check``) a missing, out-of-date or stale output; 2 = usage error.

Standard library only (Python 3.10+).
"""
from __future__ import annotations

import argparse
import difflib
import json
import os
import re
import sys
import tempfile
import unicodedata
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, Callable, Iterable, Optional, Sequence

ROOT = Path(__file__).resolve().parents[1]
_COMPANION_DIR = ROOT / "companion"
if str(_COMPANION_DIR) not in sys.path:
    sys.path.insert(0, str(_COMPANION_DIR))

# Read-only use of the companion's shared modules: the zone table/name lookup and the SPEC 3.1
# drop-id derivation, so bundled sets get exactly the ids the rest of NeedleDropper uses.
from needledropper import zones  # noqa: E402
from needledropper.models import drop_id_for, slugify  # noqa: E402

__all__ = [
    "BuiltinSet", "Issue", "PackResult", "SetGenError",
    "build_set", "camel_case", "derive_set_id", "generate", "generated_source", "lua_string",
    "load_set", "main", "normalize_spotify_id", "normalize_youtube_id", "read_pack", "render_lua",
    "source_name",
]

TOOL = "tools/gen_sets.py"
PACK_FORMAT = "needledropper-pack"
PACK_VERSION = 1
#: ``version`` of the emitted set table (the data format the in-game Sets module reads).
SET_VERSION = 1
DEFAULT_PACKS_DIR = ROOT / "packs"
DEFAULT_OUT_DIR = ROOT / "addon" / "NeedleDropper" / "Sets"
MAX_SET_ID_LEN = 40
#: Upper bound for every number written (ids, milliseconds): a signed 32-bit int is safe
#: everywhere a number goes next (Lua doubles, SavedVariables, the pixel beacon).
MAX_INT = 2**31 - 1

FIRST_LINE = "local ADDON, ns = ..."
HEADER = "-- Generated by tools/gen_sets.py from {source}. Edit the pack, not this file."
HEADER_RE = re.compile(r"-- Generated by tools/gen_sets\.py from (?P<source>.+)\. Edit the pack, not this file\.")

#: Top-level pack keys (SPEC 3.7 + SPEC-v1.2 B).
TOP_KEYS = ("format", "version", "id", "name", "author", "description", "tags", "homepage", "drops")
#: Drop keys a bundled set carries or uses (SPEC 3.7 + SPEC-v1.2 B).
DROP_KEYS = ("zone", "subzone", "areaID", "instanceID", "label", "title", "artist", "spotify", "youtube",
             "startMs", "durationMs", "note", "tags", "disabled", "id")
#: Valid SPEC 3.7 drop keys that bundled sets do not carry -> warning text (None = silently ignored).
IGNORED_DROP_KEYS: dict[str, Optional[str]] = {
    "appleMusic": None,  # SPEC-v1.1: Apple Music is out of v1; packs may keep the field, it is ignored
    "file": '"file"/"inGameFile" ignored: bundled sets ship no audio files',
    "inGameFile": '"file"/"inGameFile" ignored: bundled sets ship no audio files',
    "volume": '"volume" ignored: bundled sets do not carry a playback volume',
}

#: Key order of the emitted set header and of every emitted drop (docs/SETS-FORMAT.md).
SET_KEY_ORDER = ("id", "name", "author", "description", "tags", "version", "source", "homepage")
DROP_KEY_ORDER = ("id", "kind", "mapID", "areaID", "subzone", "instanceID", "label", "title", "artist",
                  "durationMs", "startMs", "youtube", "spotify", "tags", "note")

_SET_ID_RE = re.compile(r"(?=[a-z0-9-]*[a-z0-9])[a-z0-9-]{1,%d}" % MAX_SET_ID_LEN)
_WINDOWS_RESERVED = {"CON", "PRN", "AUX", "NUL", *(f"COM{i}" for i in range(1, 10)),
                     *(f"LPT{i}" for i in range(1, 10))}
_CONTROL_RE = re.compile(r"[\x00-\x1f\x7f]")
_URL_RE = re.compile(r"https?://[^\s\x00-\x1f\x7f]+")

# Same accepted forms as companion/needledropper/packs.py, plus the bare id; the YouTube patterns
# additionally insist that the 11-character id is not followed by more id characters.
_SPOTIFY_ID_RE = re.compile(r"[A-Za-z0-9]{22}")
_SPOTIFY_URI_RE = re.compile(r"spotify:track:([A-Za-z0-9]{22})")
_SPOTIFY_URL_RE = re.compile(r"https?://open\.spotify\.com/(?:intl-[a-z-]+/)?track/([A-Za-z0-9]{22})(?:[/?#].*)?")
_SPOTIFY_OTHER_RE = re.compile(r"(?:https?://open\.spotify\.com/(?:intl-[a-z-]+/)?|spotify:)"
                               r"(album|playlist|artist|episode|show|user)[/:]")
_YT_ID_RE = re.compile(r"[A-Za-z0-9_-]{11}")
_YT_END = r"(?![A-Za-z0-9_-]).*"
_YT_URL_RES = (
    re.compile(r"https?://(?:www\.|m\.|music\.)?youtube\.com/watch\?(?:.*?&)??v=([A-Za-z0-9_-]{11})" + _YT_END),
    re.compile(r"https?://youtu\.be/([A-Za-z0-9_-]{11})" + _YT_END),
    re.compile(r"https?://(?:www\.)?youtube(?:-nocookie)?\.com/(?:embed|shorts|live|v)/([A-Za-z0-9_-]{11})" + _YT_END),
)
_YT_PLAYLIST_RE = re.compile(r"https?://(?:www\.|m\.|music\.)?youtube\.com/playlist\?")


# ------------------------------------------------------------------ issues ----

@dataclass(frozen=True)
class Issue:
    """One validation finding, printed as
    ``packs/x.json: pack "X" drops[3] (Goldshire): missing "artist"``."""

    level: str  # "error" | "warning"
    source: str  # pack file, repo-relative (see :func:`source_name`)
    pack: str  # pack name (or the file stem until the name is known)
    message: str
    index: Optional[int] = None  # drop index in the pack's "drops" list (0-based, like JSON)
    hint: str = ""  # short context: the drop's label, subzone, zone or title

    def __str__(self) -> str:
        where = f'{self.source}: pack "{self.pack}"'
        if self.index is not None:
            where += f" drops[{self.index}]"
            if self.hint:
                where += f" ({self.hint})"
        return f"{where}: {self.message}"


class SetGenError(ValueError):
    """A pack cannot become a set. ``issues`` holds every finding (errors and warnings)."""

    def __init__(self, issues: Sequence[Issue]):
        self.issues = list(issues)
        errors = self.errors
        head = f"{len(errors)} error(s)"
        if errors:
            head += f" in {errors[0].source}"
        super().__init__(head + ":\n" + "\n".join(f"  - {e}" for e in errors))

    @property
    def errors(self) -> list[Issue]:
        return [i for i in self.issues if i.level == "error"]

    @property
    def warnings(self) -> list[Issue]:
        return [i for i in self.issues if i.level == "warning"]


class _Issues:
    """Collects the findings for one pack."""

    def __init__(self, source: str, pack: str) -> None:
        self.source = source
        self.pack = pack
        self.items: list[Issue] = []

    @property
    def error_count(self) -> int:
        return sum(1 for i in self.items if i.level == "error")

    def error(self, message: str, index: Optional[int] = None, hint: str = "") -> None:
        self.items.append(Issue("error", self.source, self.pack, message, index, hint))

    def warn(self, message: str, index: Optional[int] = None, hint: str = "") -> None:
        self.items.append(Issue("warning", self.source, self.pack, message, index, hint))


# --------------------------------------------------------------- the model ----

@dataclass
class BuiltinSet:
    """A validated set, ready to render. ``drops`` are output-ready dicts sorted by id, with
    their keys already in :data:`DROP_KEY_ORDER` (absent optional keys are simply missing)."""

    id: str
    name: str
    author: str
    description: str
    tags: list[str]
    source: str
    drops: list[dict[str, Any]]
    homepage: Optional[str] = None
    version: int = SET_VERSION
    skipped: int = 0  # drops left out because of "disabled": true
    warnings: list[Issue] = field(default_factory=list)

    @property
    def filename(self) -> str:
        """``AzerothUnbound.lua`` for set id ``azeroth-unbound``."""
        return camel_case(self.id) + ".lua"

    def to_table(self) -> dict[str, Any]:
        """The table the generated file passes to ``ns.RegisterBuiltinSet`` (as Python data)."""
        out: dict[str, Any] = {}
        for key in SET_KEY_ORDER:
            value = getattr(self, key)
            if value is not None:
                out[key] = list(value) if isinstance(value, list) else value
        out["drops"] = [dict(d) for d in self.drops]
        return out


@dataclass
class PackResult:
    """Outcome of turning one pack file into a set (see :func:`generate`)."""

    path: Path
    source: str
    set: Optional[BuiltinSet]
    issues: list[Issue]

    @property
    def ok(self) -> bool:
        return self.set is not None and not any(i.level == "error" for i in self.issues)

    @property
    def errors(self) -> list[Issue]:
        return [i for i in self.issues if i.level == "error"]


# ------------------------------------------------------------- normalizers ----

def normalize_spotify_id(value: str) -> Optional[str]:
    """Bare 22-character Spotify track id from ``spotify:track:<id>``, an
    ``https://open.spotify.com/[intl-xx/]track/<id>[?si=...]`` link or the bare id; else None."""
    v = str(value).strip()
    if _SPOTIFY_ID_RE.fullmatch(v):
        return v
    m = _SPOTIFY_URI_RE.fullmatch(v) or _SPOTIFY_URL_RE.fullmatch(v)
    return m.group(1) if m else None


def normalize_youtube_id(value: str) -> Optional[str]:
    """11-character YouTube video id from the id itself or a youtube.com ``watch?v=``,
    ``youtu.be/``, ``/embed/``, ``/shorts/``, ``/live/`` or ``/v/`` link; else None."""
    v = str(value).strip()
    if _YT_ID_RE.fullmatch(v):
        return v
    for rx in _YT_URL_RES:
        m = rx.fullmatch(v)
        if m:
            return m.group(1)
    return None


def camel_case(set_id: str) -> str:
    """``azeroth-unbound`` -> ``AzerothUnbound``, ``lo-fi-2`` -> ``LoFi2``."""
    return "".join(part[:1].upper() + part[1:] for part in set_id.split("-") if part)


def derive_set_id(name: str) -> str:
    """Set id for a pack without ``"id"`` (SPEC-v1.2 B: derived from the name): accents folded
    (``Ó`` -> ``o``), then the SPEC 3.1 slug (``models.slugify``), at most 40 characters."""
    folded = "".join(ch for ch in unicodedata.normalize("NFKD", str(name)) if not unicodedata.combining(ch))
    return slugify(folded)[:MAX_SET_ID_LEN].strip("-")


def source_name(path: str | os.PathLike[str]) -> str:
    """How a pack file is named in generated files and messages: its path relative to the
    repository root with ``/`` separators (``packs/azeroth-unbound.json``), whatever the current
    directory; just the file name for a pack outside the repository (never an absolute path)."""
    p = Path(path).resolve()
    try:
        return p.relative_to(ROOT).as_posix()
    except ValueError:
        return p.name


# --------------------------------------------------------------------- Lua ----

def lua_string(s: str) -> str:
    """A double-quoted Lua 5.1 string literal: ``\\\\ \\" \\n \\r \\t`` escaped, other control
    characters as zero-padded ``\\ddd`` (so a following digit can't extend the escape), every
    other character kept as raw UTF-8."""
    out = ['"']
    for ch in s:
        o = ord(ch)
        if ch == "\\":
            out.append("\\\\")
        elif ch == '"':
            out.append('\\"')
        elif ch == "\n":
            out.append("\\n")
        elif ch == "\r":
            out.append("\\r")
        elif ch == "\t":
            out.append("\\t")
        elif o < 32 or o == 127:
            out.append(f"\\{o:03d}")
        else:
            out.append(ch)
    out.append('"')
    return "".join(out)


def _lua_value(v: Any) -> str:
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, int):
        return str(v)
    if isinstance(v, str):
        return lua_string(v)
    if isinstance(v, (list, tuple)):
        return "{ " + ", ".join(_lua_value(x) for x in v) + " }" if v else "{}"
    raise TypeError(f"cannot write {type(v).__name__} to a set file")


def _fields(items: Iterable[tuple[str, Any]]) -> str:
    return ", ".join(f"{k} = {_lua_value(v)}" for k, v in items)


def _comment_safe(s: str) -> str:
    return _CONTROL_RE.sub("?", s)


def render_lua(s: BuiltinSet) -> str:
    """The set file's text (LF line endings, trailing newline, no timestamp)."""
    table = s.to_table()
    drops = table.pop("drops")
    lines = [
        FIRST_LINE,
        HEADER.format(source=_comment_safe(s.source)),
        "ns.RegisterBuiltinSet({",
        "  " + _fields(table.items()) + ",",
        "  drops = {",
    ]
    lines.extend("    { " + _fields(d.items()) + " }," for d in drops)
    lines += ["  },", "})"]
    return "\n".join(lines) + "\n"


def generated_source(path: str | os.PathLike[str]) -> Optional[str]:
    """The pack a set file was generated from (from its header), or None if the file does not
    exist or was not written by this tool."""
    try:
        with open(path, "r", encoding="utf-8", errors="replace", newline="") as fh:
            head = [fh.readline().rstrip("\r\n") for _ in range(2)]
    except OSError:
        return None
    if head[0] != FIRST_LINE:
        return None
    m = HEADER_RE.fullmatch(head[1])
    return m.group("source") if m else None


# -------------------------------------------------------------- validation ----

class _JsonObject(dict):
    """A JSON object that remembers keys given more than once (``json`` keeps the last)."""

    duplicate_keys: tuple[str, ...] = ()


def _json_object(pairs: list[tuple[str, Any]]) -> _JsonObject:
    obj = _JsonObject()
    dupes: list[str] = []
    for k, v in pairs:
        if k in obj and k not in dupes:
            dupes.append(k)
        obj[k] = v
    if dupes:
        obj.duplicate_keys = tuple(dupes)
    return obj


def _as_int(v: Any) -> Optional[int]:
    """Whole number from an int, an integral float or a decimal string (like packs.py)."""
    if isinstance(v, bool):
        return None
    if isinstance(v, int):
        return v
    if isinstance(v, float) and v.is_integer():
        return int(v)
    if isinstance(v, str) and v.strip().isdecimal():
        return int(v.strip())
    return None


def _encodable(s: str) -> bool:
    """False for text JSON can carry but UTF-8 cannot (unpaired surrogate escapes like \\ud83c)."""
    try:
        s.encode("utf-8")
    except UnicodeEncodeError:
        return False
    return True


def _type_name(v: Any) -> str:
    return {bool: "true/false", int: "a number", float: "a number", str: "text", list: "a list",
            dict: "an object", type(None): "null"}.get(type(v), type(v).__name__)


def _did_you_mean(word: str, choices: Iterable[str]) -> str:
    hits = difflib.get_close_matches(word, list(choices), n=1, cutoff=0.7)
    return f' (did you mean "{hits[0]}"?)' if hits else ""


def _is_comment_key(k: str) -> bool:
    """``_comment``, ``$schema``, ``// note``: JSON has no comments, these keys stand in for them."""
    return k.startswith(("_", "$", "//"))


def _text(v: Any, what: str, err: Callable[[str], None], *, required: bool = False,
          missing: str = "") -> Optional[str]:
    """Trimmed text, or None when absent/blank (reported if ``required``). Wrong types and
    text UTF-8 cannot carry are reported as errors."""
    if v is None or (isinstance(v, str) and not v.strip()):
        if required:
            err(missing or f'missing "{what}" (text)')
        return None
    if not isinstance(v, str):
        err(f'"{what}" must be text, got {_type_name(v)}')
        return None
    if not _encodable(v):
        err(f'"{what}" contains invalid text (an unpaired \\ud800-\\udfff surrogate escape)')
        return None
    return v.strip()


def _tags(v: Any, err: Callable[[str], None], warn: Callable[[str], None]) -> list[str]:
    """A list of distinct, non-empty, single-line tag strings (order kept)."""
    if v is None:
        return []
    if not isinstance(v, list):
        err(f'"tags" must be a list of text, for example ["fitting"], got {_type_name(v)}')
        return []
    out: list[str] = []
    for i, t in enumerate(v):
        if not isinstance(t, str) or not t.strip():
            err(f'"tags"[{i}] must be non-empty text, got {t!r}')
            continue
        if not _encodable(t) or _CONTROL_RE.search(t):
            err(f'"tags"[{i}] must be a single line of plain text, got {t!r}')
            continue
        t = t.strip()
        if t in out:
            warn(f'duplicate tag "{t}" listed once')
            continue
        out.append(t)
    return out


def _positive_id(entry: dict, key: str, err: Callable[[str], None]) -> Optional[int]:
    raw = entry.get(key)
    if raw is None:
        return None
    v = _as_int(raw)
    if v is None or not 0 < v <= MAX_INT:
        err(f'"{key}" must be a positive whole number, got {raw!r}')
        return None
    return v


def _millis(entry: dict, key: str, err: Callable[[str], None]) -> int:
    raw = entry.get(key)
    if raw is None:
        return 0
    v = _as_int(raw)
    if v is None or v < 0:
        err(f'"{key}" must be a whole number of milliseconds >= 0, got {raw!r}')
        return 0
    if v > MAX_INT:
        err(f'"{key}" is too large ({v} ms); the limit is {MAX_INT}')
        return 0
    return v


def _hint(entry: dict) -> str:
    """Short context for messages, like packs.py: label, subzone, zone or title."""
    for key in ("label", "subzone", "zone", "title"):
        v = entry.get(key)
        if v not in (None, "") and not isinstance(v, (dict, list)):
            return str(v)[:40]
    return ""


def _resolve_zone(entry: dict, err: Callable[[str], None],
                  warn: Callable[[str], None]) -> tuple[Optional[int], Optional[str]]:
    """``(uiMapID, canonical zone name)`` for ``"zone"`` (name, alias, ``zone:N`` or uiMapID),
    resolved through the companion's zone table exactly like packs.py."""
    zv = entry.get("zone")
    if zv is None:
        return None, None
    if isinstance(zv, bool) or not isinstance(zv, (int, float, str)):
        err(f'"zone" must be a zone name or uiMapID number, got {_type_name(zv)}')
        return None, None
    if isinstance(zv, str) and not zv.strip().isdecimal():
        if not zv.strip():
            err('"zone" is empty: give a zone name or uiMapID number')
            return None, None
        z = zones.lookup(zv)
        if z is not None:
            return z.id, z.name
        sugg = zones.suggest(zv)
        extra = (f" -- did you mean {', '.join(repr(s) for s in sugg)}?" if sugg else
                 " (run `needledropper zones` for the list, or use the uiMapID number)")
        err(f"unknown zone {zv!r}{extra}")
        return None, None
    zi = _as_int(zv)
    if zi is None or not 0 < zi <= MAX_INT:
        err(f'"zone" must be a positive whole uiMapID, got {zv!r}')
        return None, None
    z = zones.lookup(zi)
    if z is None:
        warn(f"zone {zi} is not in the known zone table (fine if it is a valid uiMapID; "
             "check with /needle where)")
        return zi, None
    return zi, z.name


def _link(entry: dict, key: str, err: Callable[[str], None]) -> Optional[str]:
    """Normalized ``spotify`` (22-char id) or ``youtube`` (11-char id); "" counts as absent."""
    raw = entry.get(key)
    if raw in (None, ""):
        return None
    norm = None
    if isinstance(raw, str):
        norm = normalize_spotify_id(raw) if key == "spotify" else normalize_youtube_id(raw)
    if norm is not None:
        return norm
    if key == "spotify":
        other = _SPOTIFY_OTHER_RE.match(raw.strip()) if isinstance(raw, str) else None
        if other:
            err(f'"spotify" is a Spotify {other.group(1)} link; use the link of the track itself, '
                f'got {raw!r}')
        else:
            err(f'"spotify" must be a Spotify track: "spotify:track:<22-character id>", an '
                f'https://open.spotify.com/track/... link or the bare 22-character id, got {raw!r}')
    else:
        if isinstance(raw, str) and _YT_PLAYLIST_RE.match(raw.strip()):
            err(f'"youtube" is a playlist link; use the link of a single video, got {raw!r}')
        else:
            err(f'"youtube" must be an 11-character video id or a YouTube video link '
                f'(watch?v=, youtu.be/, /shorts/ or /embed/), got {raw!r}')
    return None


def _build_drop(entry: dict, idx: int, issues: _Issues) -> Optional[dict[str, Any]]:
    """Validate one enabled pack drop. Returns the output-ready drop, or None after reporting
    at least one error."""
    hint = _hint(entry)

    def err(msg: str) -> None:
        issues.error(msg, idx, hint)

    def warn(msg: str) -> None:
        issues.warn(msg, idx, hint)

    errors_before = issues.error_count
    for k in getattr(entry, "duplicate_keys", ()):
        warn(f'key "{k}" is given more than once; the last one wins')
    ignored_warned: set[str] = set()
    for k in entry:
        if k in DROP_KEYS or _is_comment_key(k):
            continue
        if k in IGNORED_DROP_KEYS:
            msg = IGNORED_DROP_KEYS[k]
            if msg and msg not in ignored_warned:
                ignored_warned.add(msg)
                warn(msg)
            continue
        warn(f'unknown key "{k}" ignored{_did_you_mean(k, DROP_KEYS)}')

    # --- the song
    title = _text(entry.get("title"), "title", err, required=True, missing='missing "title" (song title, text)')
    artist = _text(entry.get("artist"), "artist", err, required=True, missing='missing "artist" (text)')

    # --- the place (same rules and precedence as companion/needledropper/packs.py)
    map_id, zone_name = _resolve_zone(entry, err, warn)
    subzone = entry.get("subzone")
    if subzone is not None:
        if not isinstance(subzone, str) or not subzone.strip() or not _encodable(subzone):
            err('"subzone" must be a non-empty name')
            subzone = None
        else:
            subzone = subzone.strip()
    area_id = _positive_id(entry, "areaID", err)
    instance_id = _positive_id(entry, "instanceID", err)
    if all(entry.get(k) is None for k in ("zone", "subzone", "areaID", "instanceID")):
        err('needs a location: "zone" (name or uiMapID), optionally "subzone"/"areaID", or "instanceID"')
    elif subzone and entry.get("zone") is None and area_id is None and instance_id is None:
        err(f'subzone {subzone!r} needs a "zone" (or an "areaID")')

    # --- timing, sources, text
    duration_ms = _millis(entry, "durationMs", err)
    start_ms = _millis(entry, "startMs", err)
    youtube = _link(entry, "youtube", err)
    spotify = _link(entry, "spotify", err)
    label = _text(entry.get("label"), "label", err)
    note = _text(entry.get("note"), "note", err)
    tags = _tags(entry.get("tags"), err, warn)

    if issues.error_count > errors_before:
        return None
    if subzone and area_id is None and instance_id is None and not slugify(subzone):
        # The id would be "sub:<mapID>:" (the companion accepts that; a shipped set must not).
        err(f'subzone {subzone!r} has no letters or digits (a-z, 0-9) to build its id from; '
            'give the landmark\'s "areaID" instead (see /needle where)')
        return None
    try:
        did = drop_id_for(mapID=map_id, subzone=subzone, areaID=area_id, instanceID=instance_id)
    except ValueError as exc:
        err(str(exc))
        return None
    explicit = entry.get("id")
    if explicit not in (None, "") and explicit != did:
        err(f'"id" {explicit!r} does not match the id derived from the location ({did!r}); '
            'remove "id" or fix the location')
        return None

    if instance_id is not None:
        kind = "instance"
    elif area_id is not None or subzone:
        kind = "subzone"
    else:
        kind = "zone"
    area = zones.lookup_area(area_id) if area_id is not None else None
    if area is not None:
        if map_id is None:
            map_id = area.zone
        elif area.zone != map_id:
            az = zones.lookup(area.zone)
            warn(f"areaID {area_id} is {area.name!r} in {az.name if az else 'zone'} ({area.zone}), "
                 f"not in zone {map_id}")
    if not label:
        if kind == "instance":
            label = f"Instance {instance_id}"
            warn('instance drops should have a "label" (shown on the title card)')
        elif kind == "subzone":
            label = subzone or (area.name if area else "") or f"Area {area_id}"
        else:
            label = zone_name or f"Zone {map_id}"
    if kind == "subzone" and not subzone and area is not None:
        subzone = area.name

    values: dict[str, Any] = {
        "id": did, "kind": kind, "mapID": map_id, "areaID": area_id, "subzone": subzone,
        "instanceID": instance_id, "label": label, "title": title, "artist": artist,
        "durationMs": duration_ms, "startMs": start_ms, "youtube": youtube, "spotify": spotify,
        "tags": tags, "note": note,
    }
    return {k: values[k] for k in DROP_KEY_ORDER if values[k] not in (None, "", [])}


def build_set(data: Any, *, source: str, name_hint: str = "pack") -> BuiltinSet:
    """Validate already-parsed pack JSON and build the set.

    ``source`` names the pack file in messages and in the output (see :func:`source_name`);
    ``name_hint`` names the pack until its ``"name"`` is read (normally the file stem).
    Raises :class:`SetGenError` listing every error (and warning) if anything is invalid.
    """
    issues = _Issues(source, name_hint)

    def fail() -> SetGenError:
        return SetGenError(issues.items)

    if not isinstance(data, dict):
        issues.error('top level must be a JSON object with "format", "name" and "drops"')
        raise fail()

    raw_name = data.get("name")
    if raw_name is None or (isinstance(raw_name, str) and not raw_name.strip()):
        issues.warn(f'missing "name"; using {name_hint!r}')
    elif not isinstance(raw_name, str):
        issues.error(f'"name" must be text, got {_type_name(raw_name)}')
    elif not _encodable(raw_name):
        issues.error('"name" contains invalid text (an unpaired \\ud800-\\udfff surrogate escape)')
    else:
        issues.pack = raw_name.strip()
    name = issues.pack

    fmt = data.get("format")
    if fmt is None:
        issues.warn(f'missing "format": "{PACK_FORMAT}"')
    elif fmt != PACK_FORMAT:
        issues.error(f'"format" must be "{PACK_FORMAT}", got {fmt!r}')
        raise fail()
    version = data.get("version", PACK_VERSION)
    if _as_int(version) != PACK_VERSION:
        issues.error(f'unsupported pack "version" {version!r} (this generator reads version {PACK_VERSION})')
        raise fail()

    for k in getattr(data, "duplicate_keys", ()):
        issues.warn(f'key "{k}" is given more than once; the last one wins')
    for k in data:
        if k not in TOP_KEYS and not _is_comment_key(k):
            issues.warn(f'unknown top-level key "{k}" ignored{_did_you_mean(k, TOP_KEYS)}')

    raw_id = data.get("id")
    set_id = ""
    if raw_id in (None, ""):
        set_id = derive_set_id(name)
        if not set_id:
            issues.error(f'cannot derive an "id" from the name {name!r}; add "id": "<lowercase-slug>"')
    elif not isinstance(raw_id, str) or not _SET_ID_RE.fullmatch(raw_id):
        suggestion = derive_set_id(raw_id if isinstance(raw_id, str) else name) or "my-soundtrack"
        issues.error(f'"id" must be 1-{MAX_SET_ID_LEN} lowercase letters, digits and dashes '
                     f'(for example "{suggestion}"), got {raw_id!r}')
    else:
        set_id = raw_id
    if set_id and camel_case(set_id).upper() in _WINDOWS_RESERVED:
        issues.error(f'set id {set_id!r} would need the file name {camel_case(set_id)}.lua, which '
                     'Windows reserves; choose another "id"')

    def top_err(msg: str) -> None:
        issues.error(msg)

    author = _text(data.get("author"), "author", top_err) or ""
    description = _text(data.get("description"), "description", top_err) or ""
    tags = _tags(data.get("tags"), top_err, issues.warn)
    homepage = _text(data.get("homepage"), "homepage", top_err) or None
    if homepage is not None and not _URL_RE.fullmatch(homepage):
        issues.error(f'"homepage" must be an http:// or https:// link, got {homepage!r}')
        homepage = None

    raw_drops = data.get("drops")
    if not isinstance(raw_drops, list):
        issues.error('"drops" must be a list')
        raise fail()

    drops: list[dict[str, Any]] = []
    first_index: dict[str, int] = {}
    skipped = 0
    for idx, entry in enumerate(raw_drops):
        if not isinstance(entry, dict):
            issues.error(f"each drop must be a JSON object, got {_type_name(entry)}", idx)
            continue
        disabled = entry.get("disabled")
        if disabled is not None and not isinstance(disabled, bool):
            issues.error(f'"disabled" must be true or false, got {disabled!r}', idx, _hint(entry))
            continue
        if disabled:
            # Skipped without further checks: a disabled entry may be a bare place (SPEC-v1.2
            # uses it to switch off an earlier soundtrack's drop) or an unfinished draft.
            skipped += 1
            continue
        drop = _build_drop(entry, idx, issues)
        if drop is None:
            continue
        if drop["id"] in first_index:
            issues.error(f"duplicate drop id {drop['id']!r} (also drops[{first_index[drop['id']]}]); "
                         'keep one, or mark the other "disabled": true', idx, drop["label"])
            continue
        first_index[drop["id"]] = idx
        drops.append(drop)

    if not drops and not issues.error_count:
        issues.error("the set has no enabled drops" if skipped else "the set has no drops")
    if issues.error_count:
        raise fail()
    drops.sort(key=lambda d: d["id"])  # plain string sort, like Map.lua's numbering (SPEC 3.2)
    return BuiltinSet(id=set_id, name=name, author=author, description=description, tags=tags,
                      source=source, drops=drops, homepage=homepage, skipped=skipped,
                      warnings=list(issues.items))


def read_pack(path: str | os.PathLike[str]) -> Any:
    """Parse a pack file (UTF-8, optional BOM). Raises :class:`SetGenError` with a readable
    message (file missing, not UTF-8, invalid JSON with line and column)."""
    p = Path(path)
    source = source_name(p)

    def fail(msg: str) -> SetGenError:
        return SetGenError([Issue("error", source, p.stem, msg)])

    try:
        raw = p.read_bytes()
    except FileNotFoundError:
        raise fail(f"pack file not found: {p}") from None
    except OSError as exc:
        raise fail(f"cannot read {p}: {exc}") from None
    try:
        text = raw.decode("utf-8-sig")
    except UnicodeDecodeError as exc:
        raise fail(f"not valid UTF-8 (byte {exc.start}); save the file as UTF-8") from None
    try:
        return json.loads(text, object_pairs_hook=_json_object)
    except json.JSONDecodeError as exc:
        raise fail(f"invalid JSON at line {exc.lineno} column {exc.colno}: {exc.msg} "
                   "(check for a missing comma or a trailing comma)") from None


def load_set(path: str | os.PathLike[str]) -> BuiltinSet:
    """Read, validate and build the set for one pack file. Raises :class:`SetGenError`."""
    p = Path(path)
    return build_set(read_pack(p), source=source_name(p), name_hint=p.stem)


def generate(paths: Iterable[str | os.PathLike[str]]) -> list[PackResult]:
    """Build a set for every pack, independently, then fail every pack involved in a clash that
    makes the output ambiguous (the same set id, or file names that differ only by case)."""
    results: list[PackResult] = []
    for path in paths:
        p = Path(path)
        try:
            s = load_set(p)
        except SetGenError as exc:
            results.append(PackResult(p, source_name(p), None, exc.issues))
        else:
            results.append(PackResult(p, s.source, s, list(s.warnings)))

    def clash(key: Callable[[BuiltinSet], str], describe: Callable[[BuiltinSet, list[PackResult]], str]) -> None:
        groups: dict[str, list[PackResult]] = {}
        for r in results:
            if r.set is not None:
                groups.setdefault(key(r.set), []).append(r)
        for group in groups.values():
            if len(group) < 2:
                continue
            # Describe every member before failing any of them (the messages name the others).
            messages = [(r, r.set.name, describe(r.set, [o for o in group if o is not r]))
                        for r in group if r.set is not None]
            for r, pack_name, message in messages:
                r.issues.append(Issue("error", r.source, pack_name, message))
                r.set = None

    clash(lambda s: s.id, lambda s, others: f'set id "{s.id}" is also used by '
          + ", ".join(o.source for o in others) + '; give each pack its own "id"')
    clash(lambda s: s.filename.lower(), lambda s, others: f"output file {s.filename} collides with "
          + ", ".join(f"{o.set.filename} ({o.source})" for o in others if o.set) + '; change one "id"')
    return results


# --------------------------------------------------------------------- CLI ----

def _display(p: Path) -> str:
    try:
        return p.resolve().relative_to(ROOT).as_posix()
    except ValueError:
        return str(p)


def _read_text_lf(path: Path) -> Optional[str]:
    """File text with CRLF folded to LF (a git autocrlf checkout is not a change); None if the
    file is missing or not UTF-8."""
    try:
        return path.read_bytes().decode("utf-8").replace("\r\n", "\n")
    except (OSError, UnicodeDecodeError):
        return None


def _atomic_write(path: Path, text: str) -> None:
    """Write UTF-8 (no BOM) with LF line endings via a temp file + rename in the same folder."""
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, tmp = tempfile.mkstemp(prefix=f".{path.name}.", suffix=".tmp", dir=str(path.parent))
    try:
        with os.fdopen(fd, "wb") as fh:
            fh.write(text.encode("utf-8"))
            fh.flush()
            os.fsync(fh.fileno())
        os.replace(tmp, path)
    except BaseException:
        try:
            os.unlink(tmp)
        except OSError:
            pass
        raise


def _toc_entries(toc: Path) -> Optional[set[str]]:
    """Lower-cased, ``/``-separated file entries of a TOC (None if unreadable)."""
    try:
        lines = toc.read_text(encoding="utf-8-sig").splitlines()
    except (OSError, UnicodeDecodeError):
        return None
    return {ln.strip().replace("\\", "/").lower() for ln in lines if ln.strip() and not ln.lstrip().startswith("#")}


def _configure_stdio() -> None:
    # Messages quote pack text (Sæglópur, Ólafur, emoji); never crash on a cp1252 pipe.
    for stream in (sys.stdout, sys.stderr):
        reconfigure = getattr(stream, "reconfigure", None)
        if reconfigure is not None:
            try:
                reconfigure(errors="backslashreplace")
            except (ValueError, OSError):
                pass


def _parser() -> argparse.ArgumentParser:
    ap = argparse.ArgumentParser(
        prog="gen_sets.py",
        description="Generate the addon's bundled soundtrack set files (Sets/*.lua) from pack JSON.",
        epilog="Default: every packs/*.json into addon/NeedleDropper/Sets. See docs/SETS-FORMAT.md.")
    ap.add_argument("packs", nargs="*", metavar="pack.json",
                    help="pack files to generate (default: every packs/*.json of the repository)")
    ap.add_argument("--out", metavar="DIR",
                    help="folder for the generated files (default: addon/NeedleDropper/Sets)")
    ap.add_argument("--check", action="store_true",
                    help="write nothing; exit 1 if a pack is invalid or an output file is missing, "
                         "out of date or (default pack list only) stale. For CI.")
    return ap


def main(argv: Optional[Sequence[str]] = None, *, packs_dir: Optional[str | os.PathLike[str]] = None,
         out_dir: Optional[str | os.PathLike[str]] = None) -> int:
    """Command-line entry point; returns the exit status. ``packs_dir``/``out_dir`` replace the
    repository defaults (``packs/``, ``addon/NeedleDropper/Sets``) for embedding and tests."""
    _configure_stdio()
    args = _parser().parse_intermixed_args(argv)
    out = Path(args.out) if args.out else Path(out_dir) if out_dir is not None else DEFAULT_OUT_DIR
    full_run = not args.packs
    if full_run:
        pdir = Path(packs_dir) if packs_dir is not None else DEFAULT_PACKS_DIR
        paths = sorted((p for p in pdir.glob("*.json") if p.is_file()), key=lambda p: p.name)
        if not paths:
            print(f"error: no pack files (*.json) in {_display(pdir)}", file=sys.stderr)
            return 1
    else:
        seen: set[Path] = set()
        paths = []
        for a in args.packs:
            rp = Path(a).resolve()
            if rp not in seen:
                seen.add(rp)
                paths.append(Path(a))

    results = generate(paths)
    failed = 0
    problems: list[str] = []  # --check findings
    produced: dict[str, PackResult] = {}  # output file name (lower) -> result
    written = unchanged = 0

    for r in results:
        for issue in r.issues:
            print(f"{'error' if issue.level == 'error' else 'warning'}: {issue}", file=sys.stderr)
        if not r.ok or r.set is None:
            failed += 1
            n_err = max(1, len(r.errors))
            print(f"FAILED {r.source}: {n_err} error(s); no set file written for it", file=sys.stderr)
            continue
        s = r.set
        target = out / s.filename
        produced[s.filename.lower()] = r
        text = render_lua(s)
        exists = target.exists()
        current = _read_text_lf(target) if exists else None
        previous = generated_source(target) if exists else None  # pack the file came from
        summary = f"{len(s.drops)} drop(s)" + (f", {s.skipped} disabled skipped" if s.skipped else "")
        if exists and previous is None:
            msg = (f"{_display(target)} exists but was not generated by {TOOL}; refusing to overwrite "
                   f"it (move it away, or give {r.source} another \"id\")")
            print(f"error: {msg}", file=sys.stderr)
            failed += 1
            continue
        # A run over explicit paths can't see every pack: don't let a copied pack that kept the
        # same set id silently replace another, still existing pack's file.
        if previous is not None and previous != r.source and (ROOT / previous).is_file():
            msg = (f"{_display(target)} holds the set generated from {previous}, which still exists; "
                   f"{r.source} has the same set id \"{s.id}\" -- give one of them another \"id\"")
            print(f"error: {msg}", file=sys.stderr)
            failed += 1
            continue
        if current == text:
            unchanged += 1
            print(f"up to date: {_display(target)} ({summary})")
            continue
        if args.check:
            state = "out of date" if exists else "missing"
            problems.append(f"{state}: {_display(target)} (from {r.source}; run: python {TOOL})")
            continue
        _atomic_write(target, text)
        written += 1
        print(f"wrote {_display(target)} ({summary}, set \"{s.id}\" from {r.source})")

    if full_run and out.is_dir():
        by_source = {r.source: r for r in results}
        for f in sorted(out.glob("*.lua"), key=lambda p: p.name):
            src = generated_source(f)
            if src is None or f.name.lower() in produced:
                continue
            owner = by_source.get(src)
            if owner is None:
                why = f"its pack {src} no longer exists"
            elif owner.set is not None and owner.set.filename != f.name:
                why = f"{src} now generates {owner.set.filename}"
            else:
                continue  # its pack is invalid right now; that is reported above
            line = f"stale: {_display(f)} ({why}); delete it and its line in NeedleDropper.toc"
            if args.check:
                problems.append(line)
            else:
                print(f"warning: {line}", file=sys.stderr)

    # The game only loads files its TOC lists: point out set files the addon's TOC (when the
    # output folder sits inside an addon) does not mention. An XML include may list them instead.
    out_abs = out.resolve()
    toc = out_abs.parent / "NeedleDropper.toc"
    entries = _toc_entries(toc) if toc.is_file() else None
    if entries is not None and not any(e.endswith(".xml") for e in entries):
        for r in results:
            if r.ok and r.set is not None and f"{out_abs.name}/{r.set.filename}".lower() not in entries:
                line = f"{out_abs.name}\\{r.set.filename}"
                print(f"warning: {line} is not listed in {_display(toc)}, so the game will not load it; "
                      f"add the line {line} after the file that defines ns.RegisterBuiltinSet",
                      file=sys.stderr)

    for line in problems:
        print(line, file=sys.stderr)
    if args.check:
        if failed or problems:
            print(f"check failed: {failed} pack(s) failed, {len(problems)} file problem(s)", file=sys.stderr)
            return 1
        print(f"ok: {unchanged} set file(s) up to date")
        return 0
    print(f"{written} written, {unchanged} up to date, {failed} failed")
    return 1 if failed else 0


if __name__ == "__main__":
    sys.exit(main())
